export function build(rt: Runtime) {
  const G = rt.stage as T;
  void G; void KILLED; void PC_FALL_OFF;

  /** when flag clicked #0 */
  function s0(t: T): void {
    rt.penClear();
    rt.broadcast("Start_Intro");
  }

  /** when I receive START_MATCH #1 */
  function s1(t: T): void {
    rt.stopAllSounds();
    rt.stopOtherScripts(t, rt.activeThread);
    G.v.Timer = "0";
    replaceItem(G.l.Stage_VisualGimmicks, "1", "0");
    rt.switchBackdrop(item(G.l.Stage_MatchData, "1"));
    rt.broadcast("GUI_InitializeMain");
  }

  /** when I receive ANIMATION #2 */
  function s2(t: T): void {
    if (eq(item(G.l.Stage_VisualGimmicks, "1"), "g")) {
      t.setEffect("color", -Infinity);
    } else {
      t.setEffect("color", "0");
    }
  }

  /** when I receive MISCTICK #3 */
  function s3(t: T): void {
    p_Timertick(t);
  }

  /** when I receive START_TITLESCREEN #4 */
  function s4(t: T): void {
    rt.switchBackdrop("TS_1_BG");
  }

  /** when I receive START_MAINMENU #5 */
  function s5(t: T): void {
    rt.switchBackdrop("TS_1_BG");
  }

  /** when I receive START_INTRO #6 */
  function s6(t: T): void {
    rt.switchBackdrop("TS_1_BG");
  }

  /** define Timertick */
  function p_Timertick(t: T): void {
    if (eq(item(G.l.Paused_Data, "1"), "-1")) {
      G.v.Timer = num(G.v.Timer) + 0.033;
    }
  }

  const scripts: ScriptDef[] = [
    { hat: 'flag', top: "bVH", plain: s0 as (t: Target) => void },
    { hat: 'broadcast', msg: "START_MATCH", top: "bVJ", plain: s1 as (t: Target) => void },
    { hat: 'broadcast', msg: "ANIMATION", top: "bVN", plain: s2 as (t: Target) => void },
    { hat: 'broadcast', msg: "MISCTICK", top: "bVR", plain: s3 as (t: Target) => void },
    { hat: 'broadcast', msg: "START_TITLESCREEN", top: "bVV", plain: s4 as (t: Target) => void },
    { hat: 'broadcast', msg: "START_MAINMENU", top: "bVX", plain: s5 as (t: Target) => void },
    { hat: 'broadcast', msg: "START_INTRO", top: "bVZ", plain: s6 as (t: Target) => void },
  ];
  return { scripts };
}
